#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

int main() {
    // Otimização de I/O
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    if (!(cin >> n)) return 0;

    vector<int> a(n);
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
    }

    // Remove elementos adjacentes duplicados
    vector<int> b;
    b.push_back(0); // Sentinela à esquerda (altura do chão)
    for (int i = 0; i < n; ++i) {
        if (b.empty() || a[i] != b.back()) {
            b.push_back(a[i]);
        }
    }
    b.push_back(0); // Sentinela à direita (altura do chão)

    int m = b.size() - 2; // Número de elementos úteis (índices 1 a m)

    // Agrupa as mudanças no número de componentes por altura
    // Cada elemento é um par (altura, delta)
    vector<pair<int, int>> changes;
    changes.reserve(m);

    for (int i = 1; i <= m; ++i) {
        if (b[i] > b[i - 1] && b[i] > b[i + 1]) {
            // Pico local: ao subir a linha além dessa altura, a componente desaparece (-1)
            changes.emplace_back(b[i], -1);
        } else if (b[i] < b[i - 1] && b[i] < b[i + 1]) {
            // Vale local: ao subir a linha além dessa altura, a componente se divide em duas (+1)
            changes.emplace_back(b[i], 1);
        }
    }

    // Ordena as mudanças pela altura
    sort(changes.begin(), changes.end());

    // Para uma altura de corte logo acima do chão, temos 1 componente conexa
    int current_components = 1;
    int max_components = 1;

    int total_changes = changes.size();
    for (int i = 0; i < total_changes; ) {
        int h = changes[i].first;
        // Aplica todas as mudanças associadas à mesma altura h
        while (i < total_changes && changes[i].first == h) {
            current_components += changes[i].second;
            i++;
        }
        // Atualiza o máximo de componentes para cortes logo acima de h
        max_components = max(max_components, current_components);
    }

    // O número total de pedaços é a base (1) + número de componentes acima do corte
    cout << 1 + max_components << "\n";

    return 0;
}
